type BE = byteorder::BigEndian;

fn start_end(buf: &Option<OffsetBufferBuilder<i32>>, i: usize) -> (usize, usize) {
	let b = buf.as_ref().unwrap();
	(b[i].try_into().unwrap(), b[i + 1].try_into().unwrap())
}

